/**
 * Shared utility functions for the application
 * Centralizes common logic to avoid duplication
 */

/**
 * Debounce function - delays execution until after wait milliseconds have elapsed
 * since the last time the debounced function was invoked
 * @param {Function} func - Function to debounce
 * @param {number} wait - Milliseconds to wait before executing
 * @return {Function} - Debounced function
 */
export function debounce(func, wait = 50) {
  let timeout
  return function executedFunction(...args) {
    const later = () => {
      clearTimeout(timeout)
      func(...args)
    }
    clearTimeout(timeout)
    timeout = setTimeout(later, wait)
  }
}

/**
 * Throttle function - limits function execution to once per specified time period
 * @param {Function} func - Function to throttle
 * @param {number} limit - Milliseconds between allowed executions
 * @return {Function} - Throttled function
 */
export function throttle(func, limit = 100) {
  let inThrottle
  return function executedFunction(...args) {
    if (!inThrottle) {
      func(...args)
      inThrottle = true
      setTimeout(() => {
        inThrottle = false
      }, limit)
    }
  }
}

/**
 * Party color mapping for consistent colors across the application
 * Used in InteractiveMapper, PartyAffiliationModal, and other components
 */
export const PARTY_COLORS = {
  Republican: '#E91D0E',
  Democrat: '#232066',
  Libertarian: '#FED105',
  Green: '#508C1B',
  Independent: '#808080',
  Constitution: '#A356DE',
  Other: '#333333',
  Unknown: '#999999',
}

/**
 * Get party color by name with fallback
 * @param {string} partyName - Name of the political party
 * @return {string} - Hex color code
 */
export function getPartyColor(partyName) {
  if (!partyName) return PARTY_COLORS.Unknown

  const normalizedName = partyName.trim().toLowerCase()

  // Check for partial matches
  if (normalizedName.includes('republican') || normalizedName === 'rep' || normalizedName === 'r') {
    return PARTY_COLORS.Republican
  }
  if (normalizedName.includes('democrat') || normalizedName === 'dem' || normalizedName === 'd') {
    return PARTY_COLORS.Democrat
  }
  if (normalizedName.includes('libertarian') || normalizedName === 'lib' || normalizedName === 'l') {
    return PARTY_COLORS.Libertarian
  }
  if (normalizedName.includes('green') || normalizedName === 'grn' || normalizedName === 'g') {
    return PARTY_COLORS.Green
  }
  if (normalizedName.includes('independent') || normalizedName === 'ind' || normalizedName === 'i') {
    return PARTY_COLORS.Independent
  }
  if (normalizedName.includes('constitution') || normalizedName === 'con' || normalizedName === 'c') {
    return PARTY_COLORS.Constitution
  }

  return PARTY_COLORS.Other
}

/**
 * Format number with commas for display
 * @param {number} num - Number to format
 * @return {string} - Formatted number string
 */
export function formatNumber(num) {
  if (num === null || num === undefined || isNaN(num)) return '0'
  return num.toLocaleString()
}

/**
 * Safely parse JSON with fallback
 * @param {string} jsonString - JSON string to parse
 * @param {*} fallback - Fallback value if parsing fails
 * @return {*} - Parsed value or fallback
 */
export function safeJsonParse(jsonString, fallback = null) {
  try {
    return JSON.parse(jsonString)
  } catch {
    return fallback
  }
}

/**
 * Check if value is empty (null, undefined, empty string, empty array, empty object)
 * @param {*} value - Value to check
 * @return {boolean} - True if empty
 */
export function isEmpty(value) {
  if (value === null || value === undefined) return true
  if (typeof value === 'string') return value.trim() === ''
  if (Array.isArray(value)) return value.length === 0
  if (typeof value === 'object') return Object.keys(value).length === 0
  return false
}
