import { ClearOutlined, DollarOutlined, PlusOutlined } from '@ant-design/icons'
import { Button, Card, DatePicker, Form, Input, InputNumber, Modal, Select, Switch, Typography } from 'antd'
import React, { memo, useCallback, useState } from 'react'
import styles from './FundraisingToolPanel.module.css'

const { Title, Text } = Typography
const { RangePicker } = DatePicker

const DONOR_TYPES = ['Individual', 'Corporate', 'PAC', 'Small Dollar']
const METHODS = ['Online', 'Event', 'Direct Mail', 'PAC']

function FundraisingToolPanel({ filters, updateFilters, clearFilters, fundraisingGoal, setGoal, addDonation }) {
  const [addModalVisible, setAddModalVisible] = useState(false)
  const [form] = Form.useForm()

  const handleDateChange = useCallback((dates, dateStrings) => {
    updateFilters({ dateRange: dateStrings[0] ? dateStrings : null })
  }, [updateFilters])

  const handleDonorTypeChange = useCallback((value) => {
    updateFilters({ donorType: value || null })
  }, [updateFilters])

  const handleMinAmount = useCallback((value) => {
    updateFilters({ amountRange: { ...filters.amountRange, min: value } })
  }, [updateFilters, filters.amountRange])

  const handleMaxAmount = useCallback((value) => {
    updateFilters({ amountRange: { ...filters.amountRange, max: value } })
  }, [updateFilters, filters.amountRange])

  const handleAddDonation = useCallback((values) => {
    addDonation({
      ...values,
      date: values.date ? values.date.format('YYYY-MM-DD') : new Date().toISOString().split('T')[0],
      isRecurring: !!values.isRecurring,
    })
    form.resetFields()
    setAddModalVisible(false)
  }, [addDonation, form])

  return (
    <div className={styles.toolPanel}>
      <Title level={5} className={styles.panelTitle}>
        <DollarOutlined /> Fundraising
      </Title>

      <Button type="primary" icon={<PlusOutlined />} onClick={() => setAddModalVisible(true)} block className={styles.addButton}>
        Add Donation
      </Button>

      <Card size="small" className={styles.card}>
        <Text strong>Campaign Goal</Text>
        <InputNumber
          value={fundraisingGoal}
          onChange={setGoal}
          formatter={(value) => `$ ${value}`.replace(/\B(?=(\d{3})+(?!\d))/g, ',')}
          parser={(value) => value.replace(/\$\s?|(,*)/g, '')}
          className={styles.fullWidth}
          min={0}
        />
      </Card>

      <Card size="small" className={styles.card}>
        <Text strong>Date Range</Text>
        <RangePicker onChange={handleDateChange} className={styles.fullWidth} size="small" />
      </Card>

      <Card size="small" className={styles.card}>
        <Text strong>Donor Type</Text>
        <Select
          placeholder="All Types"
          value={filters.donorType}
          onChange={handleDonorTypeChange}
          allowClear
          className={styles.fullWidth}
          options={DONOR_TYPES.map((t) => ({ value: t, label: t }))}
        />
      </Card>

      <Card size="small" className={styles.card}>
        <Text strong>Amount Range</Text>
        <div className={styles.amountRow}>
          <InputNumber placeholder="Min" value={filters.amountRange.min} onChange={handleMinAmount} prefix="$" size="small" />
          <span>to</span>
          <InputNumber placeholder="Max" value={filters.amountRange.max} onChange={handleMaxAmount} prefix="$" size="small" />
        </div>
      </Card>

      <Button icon={<ClearOutlined />} onClick={clearFilters} block>Clear Filters</Button>

      <Modal
        title="Add Donation"
        open={addModalVisible}
        onCancel={() => setAddModalVisible(false)}
        footer={null}
      >
        <Form form={form} layout="vertical" onFinish={handleAddDonation}>
          <Form.Item name="donorName" label="Donor Name" rules={[{ required: true, message: 'Required' }]}>
            <Input />
          </Form.Item>
          <Form.Item name="amount" label="Amount" rules={[{ required: true, message: 'Required' }]}>
            <InputNumber prefix="$" min={1} className={styles.fullWidth} />
          </Form.Item>
          <Form.Item name="method" label="Method" rules={[{ required: true, message: 'Required' }]}>
            <Select options={METHODS.map((m) => ({ value: m, label: m }))} />
          </Form.Item>
          <Form.Item name="donorType" label="Donor Type" rules={[{ required: true, message: 'Required' }]}>
            <Select options={DONOR_TYPES.map((t) => ({ value: t, label: t }))} />
          </Form.Item>
          <Form.Item name="email" label="Email"><Input /></Form.Item>
          <Form.Item name="city" label="City"><Input /></Form.Item>
          <Form.Item name="isRecurring" label="Recurring" valuePropName="checked"><Switch /></Form.Item>
          <Form.Item>
            <Button type="primary" htmlType="submit" block>Add Donation</Button>
          </Form.Item>
        </Form>
      </Modal>
    </div>
  )
}

export default memo(FundraisingToolPanel)
