import React from 'react'
import useFundraisingData from './hooks/useFundraisingData.jsx'
import FundraisingToolPanel from './FundraisingToolPanel.jsx'
import FundraisingDashboard from './FundraisingDashboard.jsx'
import styles from './FundraisingContainer.module.css'

const FundraisingContainer = () => {
  const fundraisingData = useFundraisingData()

  return (
    <div className={styles.container}>
      <FundraisingToolPanel
        filters={fundraisingData.filters}
        updateFilters={fundraisingData.updateFilters}
        clearFilters={fundraisingData.clearFilters}
        fundraisingGoal={fundraisingData.fundraisingGoal}
        setGoal={fundraisingData.setGoal}
        addDonation={fundraisingData.addDonation}
      />
      <FundraisingDashboard
        filteredDonations={fundraisingData.filteredDonations}
        summaryStats={fundraisingData.summaryStats}
        methodBreakdown={fundraisingData.methodBreakdown}
        topDonors={fundraisingData.topDonors}
        monthlyTrend={fundraisingData.monthlyTrend}
        goalProgress={fundraisingData.goalProgress}
        fundraisingGoal={fundraisingData.fundraisingGoal}
      />
    </div>
  )
}

export default FundraisingContainer
