import { Button, Layout, Typography } from 'antd'
import React, { memo, useCallback } from 'react'
import { useNavigate } from 'react-router-dom'
import LoadingScreen from '../LoadingScreen.jsx'
import { usePermissions } from '../auth/Permissions.jsx'
import Auth from '../auth/auth.jsx'
import ErrorBoundary from '../components/ErrorBoundary.jsx'
import CustomHeader from '../components/CustomHeader.jsx'
import AppFooter from '../components/Footer.jsx'
import Sidebar from '../components/SideBar.jsx'
import useSessionValidation from '../hooks/useSessionValidation.jsx'
import FundraisingContainer from '../fundraising/FundraisingContainer.jsx'
import styles from './FundraisingApp.module.css'

const { Content } = Layout
const { Text } = Typography

const UserHeader = memo(function UserHeader({ displayName, onLogout, onTitleClick }) {
  return (
    <div className={styles.userContainer}>
      <div className={styles.textContainer}>
        <Text className={styles.welcomeText}>Welcome, {displayName}</Text>
      </div>
      <div className={styles.titleContainer}>
        <Text className={styles.interactiveTitle} onClick={onTitleClick}>
          Fundraising Analytics
        </Text>
      </div>
      <div>
        <Button className={styles.actionButton} onClick={onLogout}>
          Logout
        </Button>
      </div>
    </div>
  )
})

function FundraisingApp() {
  const { user, handleSignOut } = usePermissions()
  const { isLoading } = useSessionValidation(user)
  const navigate = useNavigate()

  const handleTitleClick = useCallback(() => {
    navigate('/campaign-tools')
  }, [navigate])

  if (isLoading) {
    return <LoadingScreen />
  }

  return (
    <>
      <Layout className={styles.campaignLayout}>
        <CustomHeader />
        <Layout>
          <Sidebar user={user} />
          <Content className={styles.content}>
            {user ? (
              <>
                <UserHeader
                  displayName={user.displayName}
                  onLogout={handleSignOut}
                  onTitleClick={handleTitleClick}
                />
                <div className={styles.divider} />
                <ErrorBoundary>
                  <FundraisingContainer />
                </ErrorBoundary>
              </>
            ) : (
              <Auth />
            )}
          </Content>
        </Layout>
      </Layout>
      <AppFooter />
    </>
  )
}

export default FundraisingApp
