import { Card, Col, Progress, Row, Statistic, Table, Tag } from 'antd'
import React, { memo, useMemo } from 'react'
import styles from './FundraisingDashboard.module.css'

const TYPE_COLORS = { 'Individual': 'blue', 'Corporate': 'purple', 'PAC': 'gold', 'Small Dollar': 'green' }

function FundraisingDashboard({ filteredDonations, summaryStats, methodBreakdown, topDonors, monthlyTrend, goalProgress, fundraisingGoal }) {
  const recentDonations = useMemo(() =>
    [...filteredDonations].sort((a, b) => b.date.localeCompare(a.date)).slice(0, 20),
  [filteredDonations])

  const maxMonthly = useMemo(() =>
    Math.max(...monthlyTrend.map((m) => m.total), 1),
  [monthlyTrend])

  const methodTotal = useMemo(() =>
    methodBreakdown.reduce((sum, m) => sum + m.total, 0) || 1,
  [methodBreakdown])

  return (
    <div className={styles.dashboard}>
      <Row gutter={[16, 16]}>
        <Col xs={24} sm={8} md={6}>
          <Card size="small" className={styles.goalCard}>
            <Progress type="circle" percent={goalProgress} size={100} />
            <div className={styles.goalText}>
              <Statistic title="Goal" value={fundraisingGoal} prefix="$" valueStyle={{ fontSize: '14px' }} />
            </div>
          </Card>
        </Col>
        <Col xs={12} sm={8} md={4}>
          <Card size="small"><Statistic title="Total Raised" value={summaryStats.totalRaised} prefix="$" valueStyle={{ color: '#3f8600' }} /></Card>
        </Col>
        <Col xs={12} sm={8} md={4}>
          <Card size="small"><Statistic title="Avg Donation" value={summaryStats.avgDonation} prefix="$" /></Card>
        </Col>
        <Col xs={12} sm={8} md={4}>
          <Card size="small"><Statistic title="Donors" value={summaryStats.donorCount} /></Card>
        </Col>
        <Col xs={12} sm={8} md={6}>
          <Card size="small"><Statistic title="Recurring Revenue" value={summaryStats.recurringRevenue} prefix="$" valueStyle={{ color: '#1890ff' }} /></Card>
        </Col>
      </Row>

      <Row gutter={[16, 16]} className={styles.sectionRow}>
        <Col xs={24} md={12}>
          <Card title="Donation Methods" size="small">
            {methodBreakdown.map((m) => (
              <div key={m.method} className={styles.methodRow}>
                <span className={styles.methodLabel}>{m.method}</span>
                <Progress percent={Math.round((m.total / methodTotal) * 100)} format={() => `$${m.total.toLocaleString()}`} />
              </div>
            ))}
          </Card>
        </Col>
        <Col xs={24} md={12}>
          <Card title="Monthly Trend" size="small">
            {monthlyTrend.map((m) => (
              <div key={m.month} className={styles.methodRow}>
                <span className={styles.methodLabel}>{m.month}</span>
                <Progress percent={Math.round((m.total / maxMonthly) * 100)} format={() => `$${m.total.toLocaleString()}`} strokeColor="#52c41a" />
              </div>
            ))}
          </Card>
        </Col>
      </Row>

      <Row gutter={[16, 16]} className={styles.sectionRow}>
        <Col xs={24} md={14}>
          <Card title="Recent Donations" size="small">
            <Table
              dataSource={recentDonations.map((d) => ({ ...d, key: d.id }))}
              columns={[
                { title: 'Donor', dataIndex: 'donorName', key: 'donorName', width: 160 },
                { title: 'Amount', dataIndex: 'amount', key: 'amount', width: 100,
                  render: (v) => `$${v.toLocaleString()}`,
                  sorter: (a, b) => a.amount - b.amount,
                },
                { title: 'Date', dataIndex: 'date', key: 'date', width: 110 },
                { title: 'Method', dataIndex: 'method', key: 'method', width: 100 },
                { title: 'Type', dataIndex: 'donorType', key: 'donorType', width: 110,
                  render: (v) => <Tag color={TYPE_COLORS[v]}>{v}</Tag>,
                },
              ]}
              size="small"
              pagination={{ pageSize: 8 }}
              scroll={{ x: 600 }}
            />
          </Card>
        </Col>
        <Col xs={24} md={10}>
          <Card title="Top Donors" size="small">
            <Table
              dataSource={topDonors.map((d, i) => ({ ...d, key: i, rank: i + 1 }))}
              columns={[
                { title: '#', dataIndex: 'rank', key: 'rank', width: 40 },
                { title: 'Donor', dataIndex: 'name', key: 'name', width: 160 },
                { title: 'Total', dataIndex: 'total', key: 'total', width: 100,
                  render: (v) => `$${v.toLocaleString()}`,
                },
                { title: 'City', dataIndex: 'city', key: 'city', width: 100 },
              ]}
              size="small"
              pagination={false}
            />
          </Card>
        </Col>
      </Row>
    </div>
  )
}

export default memo(FundraisingDashboard)
