import { useCallback, useMemo, useState } from 'react'
import sampleDonations from '../data/sampleDonationData.js'

const useFundraisingData = () => {
  const [donations, setDonations] = useState(sampleDonations)
  const [fundraisingGoal, setFundraisingGoal] = useState(500000)
  const [filters, setFilters] = useState({
    dateRange: null,
    donorType: null,
    amountRange: { min: null, max: null },
  })

  const filteredDonations = useMemo(() => {
    let result = donations

    if (filters.donorType) {
      result = result.filter((d) => d.donorType === filters.donorType)
    }
    if (filters.dateRange && filters.dateRange[0] && filters.dateRange[1]) {
      result = result.filter((d) => d.date >= filters.dateRange[0] && d.date <= filters.dateRange[1])
    }
    if (filters.amountRange.min !== null && filters.amountRange.min !== undefined) {
      result = result.filter((d) => d.amount >= filters.amountRange.min)
    }
    if (filters.amountRange.max !== null && filters.amountRange.max !== undefined) {
      result = result.filter((d) => d.amount <= filters.amountRange.max)
    }

    return result
  }, [donations, filters])

  const summaryStats = useMemo(() => {
    const totalRaised = filteredDonations.reduce((sum, d) => sum + d.amount, 0)
    const donorCount = new Set(filteredDonations.map((d) => d.donorName)).size
    const avgDonation = filteredDonations.length > 0 ? totalRaised / filteredDonations.length : 0
    const recurringRevenue = filteredDonations.filter((d) => d.isRecurring).reduce((sum, d) => sum + d.amount, 0)

    return { totalRaised, avgDonation: Math.round(avgDonation), donorCount, recurringRevenue }
  }, [filteredDonations])

  const methodBreakdown = useMemo(() => {
    const methods = ['Online', 'Event', 'Direct Mail', 'PAC']
    return methods.map((method) => {
      const methodDonations = filteredDonations.filter((d) => d.method === method)
      const total = methodDonations.reduce((sum, d) => sum + d.amount, 0)
      return { method, count: methodDonations.length, total }
    })
  }, [filteredDonations])

  const topDonors = useMemo(() => {
    const donorMap = {}
    filteredDonations.forEach((d) => {
      if (!donorMap[d.donorName]) {
        donorMap[d.donorName] = { name: d.donorName, total: 0, count: 0, type: d.donorType, city: d.city }
      }
      donorMap[d.donorName].total += d.amount
      donorMap[d.donorName].count += 1
    })
    return Object.values(donorMap).sort((a, b) => b.total - a.total).slice(0, 10)
  }, [filteredDonations])

  const monthlyTrend = useMemo(() => {
    const months = {}
    filteredDonations.forEach((d) => {
      const month = d.date.substring(0, 7)
      if (!months[month]) months[month] = 0
      months[month] += d.amount
    })
    return Object.entries(months)
        .sort(([a], [b]) => a.localeCompare(b))
        .slice(-6)
        .map(([month, total]) => ({ month, total }))
  }, [filteredDonations])

  const goalProgress = useMemo(() => {
    if (fundraisingGoal <= 0) return 0
    return Math.min(100, Math.round((summaryStats.totalRaised / fundraisingGoal) * 100))
  }, [summaryStats.totalRaised, fundraisingGoal])

  const addDonation = useCallback((donationData) => {
    setDonations((prev) => [...prev, { ...donationData, id: String(Date.now()) }])
  }, [])

  const updateFilters = useCallback((newFilters) => {
    setFilters((prev) => ({ ...prev, ...newFilters }))
  }, [])

  const clearFilters = useCallback(() => {
    setFilters({ dateRange: null, donorType: null, amountRange: { min: null, max: null } })
  }, [])

  const setGoal = useCallback((amount) => {
    setFundraisingGoal(amount)
  }, [])

  return {
    donations,
    filteredDonations,
    fundraisingGoal,
    filters,
    summaryStats,
    methodBreakdown,
    topDonors,
    monthlyTrend,
    goalProgress,
    addDonation,
    updateFilters,
    clearFilters,
    setGoal,
  }
}

export default useFundraisingData
